set-variable.value:
@{
        var originalBody = (string)context.Variables.GetValueOrDefault("hl_original_body", "");
        if (string.IsNullOrEmpty(originalBody)) {
            return false;
        }
        try {
            var parsed = JObject.Parse(originalBody);
            var streamToken = parsed["stream"];
            return streamToken != null && streamToken.Type == JTokenType.Boolean && (bool)streamToken;
        } catch {
            return false;
        }
    }

send-request.set-body:
@{
                    var body = JObject.Parse((string)context.Variables["hl_original_response"]);
                    var choices = body["choices"] as JArray ?? new JArray();
                    var outputMessages = new JArray();
                    foreach (var choice in choices) {
                        var msg = choice["message"];
                        if (msg != null) {
                            outputMessages.Add(msg);
                        }
                    }
                    var v1Body = new JObject {
                        ["metadata"] = new JObject {
                            ["model"] = (string)context.Variables.GetValueOrDefault("hl_model", ""),
                            ["requester_id"] = (string)context.Variables.GetValueOrDefault("hl_requester_id", ""),
                            ["provider"] = (string)context.Variables.GetValueOrDefault("hl_provider", "azure-apim")
                        },
                        ["output"] = new JObject {
                            ["messages"] = outputMessages
                        }
                    };
                    return v1Body.ToString();
                }

when.set-body:
@{
                                var evalJson = (JObject)context.Variables["hl_eval_output_json"];
                                var threatLevel = (string)(evalJson["evaluation"]?["threat_level"] ?? "unknown");
                                var blockMsg = $"This response has been blocked by HiddenLayer AI security. Threat level: {threatLevel}";
                                var resp = new JObject {
                                    ["id"] = "hl-blocked",
                                    ["object"] = "chat.completion",
                                    ["choices"] = new JArray {
                                        new JObject {
                                            ["index"] = 0,
                                            ["message"] = new JObject {
                                                ["role"] = "assistant",
                                                ["content"] = blockMsg
                                            },
                                            ["finish_reason"] = "stop"
                                        }
                                    }
                                };
                                return resp.ToString();
                            }

@{
                                var evalJson = (JObject)context.Variables["hl_eval_output_json"];
                                var redactedMessages = evalJson["modified_data"]?["output"]?["messages"] as JArray;
                                if (redactedMessages != null) {
                                    var original = JObject.Parse((string)context.Variables["hl_original_response"]);
                                    var choices = original["choices"] as JArray ?? new JArray();
                                    for (int i = 0; i < choices.Count && i < redactedMessages.Count; i++) {
                                        choices[i]["message"] = redactedMessages[i];
                                    }
                                    return original.ToString();
                                }
                                return (string)context.Variables["hl_original_response"];
                            }
